pub(super) fn release__has_migration_hard_dq(mut report: Value) -> Result<Value> {
    let mut decision: Value;
    if equal(
        &release__report_readiness_effect(report.clone())?,
        &json!("hard_dq"),
    ) {
        return Ok(json!(true));
    }
    decision = unary_method(
        &json!(values::text(&{
            let first = get(&report, &json!("compatibility_decision"), Value::Null);
            if truth(&first) {
                first
            } else {
                {
                    let first = get(&report, &json!("compatibility_class"), Value::Null);
                    if truth(&first) { first } else { json!("") }
                }
            }
        })),
        "lower",
        &Value::Null,
    )?;
    if contains(
        &unique(vec![
            json!("hard_dq"),
            json!("blocked"),
            json!("unsupported"),
        ]),
        &decision,
    ) {
        return Ok(json!(true));
    }
    return Ok(builtin(
        "any",
        &[{
            let mut collected_values = Vec::new();
            for current in sequence(&get(&report, &json!("findings"), Value::Array(vec![])))? {
                let mut finding = current;
                if !(finding.clone().is_object()) {
                    continue;
                }
                collected_values.push(json!(equal(
                    &unary_method(
                        &json!(values::text(&{
                            let first = get(&finding, &json!("readiness_effect"), Value::Null);
                            if truth(&first) { first } else { json!("") }
                        })),
                        "lower",
                        &Value::Null
                    )?,
                    &json!("hard_dq")
                )));
            }
            Value::Array(collected_values)
        }],
    )?);
}

