pub(super) fn release__report_readiness_effect(mut report: Value) -> Result<Value> {
    let mut candidates: Value;
    let mut lowered: Value;
    candidates = Value::Array(vec![
        get(&report, &json!("readiness_effect"), Value::Null),
        get(&report, &json!("verdict"), Value::Null),
        get(&report, &json!("status"), Value::Null),
        get(
            &{
                let first = get(&report, &json!("summary"), Value::Null);
                if truth(&first) { first } else { json!({}) }
            },
            &json!("readiness_effect"),
            Value::Null,
        ),
        get(
            &{
                let first = get(&report, &json!("summary"), Value::Null);
                if truth(&first) { first } else { json!({}) }
            },
            &json!("overall_status"),
            Value::Null,
        ),
    ]);
    lowered = {
        let mut collected_values = Vec::new();
        for current in sequence(&candidates)? {
            let mut item = current;
            if !(!equal(&item, &Value::Null)) {
                continue;
            }
            collected_values.push(unary_method(
                &json!(values::text(&item)),
                "lower",
                &Value::Null,
            )?);
        }
        unique(collected_values)
    };
    if truth(&arithmetic(
        &lowered,
        &unique(vec![
            json!("hard_dq"),
            json!("blocked"),
            json!("fail"),
            json!("failed"),
        ]),
        "&",
    )?) {
        return Ok(json!("hard_dq"));
    }
    if truth(&arithmetic(
        &lowered,
        &unique(vec![json!("hold"), json!("pending")]),
        "&",
    )?) {
        return Ok(json!("hold"));
    }
    if truth(&arithmetic(
        &lowered,
        &unique(vec![json!("soft_gap"), json!("warning")]),
        "&",
    )?) {
        return Ok(json!("soft_gap"));
    }
    return Ok(json!("pass"));
}

